<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">LEDGER</div><h1>Transactions</h1><p>Financially relevant events recorded once per successful payment.</p></div></div><div class="panel"><form class="toolbar"><input name="q" value="<?php echo e(request('q')); ?>" placeholder="Reference or gateway transaction ID"><select name="type"><option value="">All types</option><?php $__currentLoopData = ['payment','refund','adjustment','fee','credit','debit']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $t): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($t); ?>" <?php if(request('type')===$t): echo 'selected'; endif; ?>><?php echo e(ucfirst($t)); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><button class="btn secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Business</th><th>Type</th><th>Amount</th><th>Gateway</th><th>Status</th><th>Created</th></tr></thead><tbody><?php $__currentLoopData = $transactions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $t): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td class="mono"><?php echo e($t->reference); ?></td><td><?php echo e($t->business->name); ?></td><td><span class="badge neutral"><?php echo e(ucfirst($t->transaction_type->value)); ?></span></td><td>₹<?php echo e(number_format($t->net_amount,2)); ?></td><td><?php echo e(strtoupper($t->gateway ?: '—')); ?></td><td><span class="badge <?php echo e($t->status==='successful'?'success':'neutral'); ?>"><?php echo e(ucfirst($t->status)); ?></span></td><td><?php echo e($t->created_at->format('d M Y H:i')); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div><div class="pagination"><?php echo e($transactions->links()); ?></div></div><?php $__env->stopSection(); ?>

